const sphereTopologies=new Map();
function sphereTopology(segments){
 let topology=sphereTopologies.get(segments);if(topology)return topology;
 const points=[],indices=[];
 for(let ring=0;ring<=5;ring++)for(let slice=0;slice<=segments;slice++){
  const latitude=Math.PI*ring/5,azimuth=slice*Math.PI*2/segments;
  const sine=ring===0||ring===5?0:Math.sin(latitude);
  points.push(sine*Math.cos(azimuth),Math.cos(latitude),sine*Math.sin(azimuth));
 }
 for(let ring=0;ring<5;ring++)for(let slice=0;slice<segments;slice++){
  const a=ring*(segments+1)+slice,b=a+1,c=a+segments+1,d=c+1;
  if(ring===0)indices.push(a,d,c);else if(ring===4)indices.push(a,b,c);else indices.push(a,b,d,a,d,c);
 }
 topology={points:new Float64Array(points),indices:new Uint16Array(indices)};
 if(sphereTopologies.size>=16)sphereTopologies.delete(sphereTopologies.keys().next().value);
 sphereTopologies.set(segments,topology);return topology;
}

// Smooth normals use the actual changing cheek/jaw cross-sections. They
// remain identical at shared vertices rather than faceting every skin panel.
const surface=(ring,index)=>{
 const r=rings[ring],previous=rings[Math.max(0,ring-1)],next=rings[Math.min(rings.length-1,ring+1)],dy=next.y-previous.y;
 const a=index*2*Math.PI/n,sa=Math.sin(a),ca=Math.cos(a),nx=sa/r.rx,nz=ca/r.rz;
 const ny=-(nx*sa*(next.rx-previous.rx)+nz*(ca*(next.rz-previous.rz)+next.z-previous.z))/dy;
 const length=Math.hypot(nx,ny,nz);return {p:vertex(r,index),normal:[nx/length,ny/length,nz/length]};
};
const skinTriangle=(a,b,c)=>{for(const v of [a,b,c])data.push(...v.p,...v.normal,...skin,currentMaterial)};

const rigidCitizenMeshes=new Map();let rigidBuilds=0,rigidHits=0;
function clearCitizenMeshes(){rigidCitizenMeshes.clear()}
function appendCitizenIdentity(p,idx,x,y,z,size){
 const key=idx+':'+p.job;let mesh=rigidCitizenMeshes.get(key);
 if(!mesh){
  const target=data,old=currentMaterial;data=[];currentMaterial=MATERIAL.WOOD;
  try{buildCitizenIdentity(idx,p.job);mesh=new Float32Array(data)}finally{data=target;currentMaterial=old}
  if(rigidCitizenMeshes.size>=32)rigidCitizenMeshes.delete(rigidCitizenMeshes.keys().next().value);
  rigidCitizenMeshes.set(key,mesh);rigidBuilds++;
 }else rigidHits++;
 for(let i=0;i<mesh.length;i+=10)data.push(x+mesh[i]*size,y+mesh[i+1]*size,z+mesh[i+2]*size,mesh[i+3],mesh[i+4],mesh[i+5],mesh[i+6],mesh[i+7],mesh[i+8],mesh[i+9]);

function buildCitizenIdentity(idx,job){
 const x=0,y=0,z=0,size=1,p={job};
 const skin=rgb([0xd5a781,0x95654b,0xefc19c,0xbe8968,0x9a6a48][(idx+names.length)%5]),hair=rgb([0x4c3228,0x342f29,0x8b633f,0x664b36,0xa18b65][(idx+4)%5]);
 const trim=rgb([0xf2cb79,0x82b5b2,0xf0b9a0,0xe1d3a3,0xaac6d1,0xd7a9c8][idx%6]);

}
function livingPresentationStats(){let rigidBytes=0;for(const mesh of rigidCitizenMeshes.values())rigidBytes+=mesh.byteLength;return {...livingForest,rigidBuilds,rigidHits,rigidEntries:rigidCitizenMeshes.size,rigidBytes,rigidLimit:32,topologyEntries:sphereTopologies.size};}
function villager(p){const vertexStart=data.length;let x=p.x,z=p.z,y=terrain(x,z),u=p.phase,idx=Math.max(0,people.indexOf(p)),size=.92+(idx%5)*.045;let c=colors[jobs.indexOf(p.job)]||colors[0],skin=rgb([0xd5a781,0x95654b,0xefc19c,0xbe8968,0x9a6a48][(idx+names.length)%5]),hair=rgb([0x4c3228,0x342f29,0x8b633f,0x664b36,0xa18b65][(idx+4)%5]);const busy=p.activity.toLowerCase().includes('harvest')||p.activity.toLowerCase().includes('cutting')||p.activity.toLowerCase().includes('craft')||p.activity.toLowerCase().includes('construct');let pace=p.activity.includes('Traveling')||p.activity.includes('Explor')?1:.23,step=Math.sin(u*2.7)*.21*pace;
// Individual fitted wool coats: flared hem, waist, chest, collar, gait sway.
const rig=citizenRigPose(p);
const outfitTrim=[0xf2cb79,0x82b5b2,0xf0b9a0,0xe1d3a3,0xaac6d1,0xd7a9c8].map(rgb);
const trim=outfitTrim[idx%outfitTrim.length];
tailoredGarment(x,y,z,size,c,trim,garmentProfile(p,idx,rig));
box(x,y+.685*size,z+.211*size,.078*size,.082*size,.026*size,rgb(0xd9c091));
// Individual gait, boots, hands, long sleeves and silhouettes.
const worldJoint=q=>[x+q[0]*size,y+q[1]*size,z+q[2]*size];
for(let sideIndex=0;sideIndex<2;sideIndex++){
 const leg=rig.legs[sideIndex],arm=rig.arms[sideIndex];
 limbSegment(worldJoint(leg.hip),worldJoint(leg.knee),.091*size,rgb(0x534637));
 limbSegment(worldJoint(leg.knee),worldJoint(leg.ankle),.076*size,rgb(0x534637));
 ellipsoid(...worldJoint(leg.knee),.096*size,.094*size,.097*size,rgb(0x534637),7);
 const foot=worldJoint(leg.ankle);
 box(foot[0],foot[1]-.11*size,foot[2]+.08*size,.185*size,.026*size,.30*size,rgb(0x302a23));
 ellipsoid(foot[0],foot[1]-.044*size,foot[2]+.095*size,.096*size,.064*size,.16*size,rgb(0x574434),8);
 limbSegment(worldJoint(arm.shoulder),worldJoint(arm.elbow),.091*size,c);
 limbSegment(worldJoint(arm.elbow),worldJoint(arm.wrist),.077*size,c);
 ellipsoid(...worldJoint(arm.elbow),.084*size,.084*size,.084*size,c,7);
 ellipsoid(...worldJoint(arm.wrist),.072*size,.091*size,.067*size,skin,8);
 const thumb=worldJoint([arm.wrist[0]+(sideIndex===0?.046:-.046),arm.wrist[1]-.018,arm.wrist[2]+.054]);
 ellipsoid(...thumb,.026*size,.043*size,.034*size,skin,6);
}
appendCitizenIdentity(p,idx,x,y,z,size);
